pre_install:
$bootstrap = @'
$ErrorActionPreference = 'Stop'

$originalAppData = [string]$env:RECORDLY_ORIGINAL_APPDATA
$persistAppData = [string]$env:RECORDLY_PERSIST_APPDATA

if ([string]::IsNullOrWhiteSpace($originalAppData)) {
  throw 'The original Windows APPDATA path was not supplied by Recordly.cmd.'
}
if ([string]::IsNullOrWhiteSpace($persistAppData)) {
  throw 'The Scoop persist AppData path was not supplied by Recordly.cmd.'
}

$originalAppData = [System.IO.Path]::GetFullPath($originalAppData).TrimEnd([char]92)
$persistAppData = [System.IO.Path]::GetFullPath($persistAppData).TrimEnd([char]92)
$systemUserData = Join-Path $originalAppData 'Recordly'
$persistUserData = Join-Path $persistAppData 'Recordly'

New-Item -ItemType Directory -Path $persistAppData -Force | Out-Null

if (Test-Path -LiteralPath $systemUserData) {
  $existing = Get-Item -LiteralPath $systemUserData -Force

  if ($existing.Attributes.HasFlag([System.IO.FileAttributes]::ReparsePoint)) {
    $existingTarget = [string]$existing.Target
    if ([string]::IsNullOrWhiteSpace($existingTarget)) {
      throw "Existing Recordly userData is a reparse point with no readable target: $systemUserData"
    }

    $existingTarget = [System.IO.Path]::GetFullPath($existingTarget).TrimEnd([char]92)
    if (-not [string]::Equals($existingTarget, $persistUserData, [System.StringComparison]::OrdinalIgnoreCase)) {
      throw "Refusing to replace an existing Recordly userData link. Current target: $existingTarget; expected: $persistUserData"
    }

    if (-not (Test-Path -LiteralPath $persistUserData -PathType Container)) {
      throw "Existing Recordly userData Junction points to a missing persist directory: $persistUserData"
    }

    Write-Host "Recordly userData Junction already points to Scoop persist: $existingTarget"
    exit 0
  }

  if (-not $existing.PSIsContainer) {
    throw "The existing Recordly userData path is not a directory: $systemUserData"
  }

  New-Item -ItemType Directory -Path $persistUserData -Force | Out-Null
  $sourceItems = @(Get-ChildItem -LiteralPath $systemUserData -Force -ErrorAction Stop)

  if ($sourceItems.Count -gt 0) {
    Write-Host "Migrating existing Recordly userData to Scoop persist without overwriting files already there."
    & robocopy.exe $systemUserData $persistUserData /E /XC /XN /XO /COPY:DAT /DCOPY:DAT /XJ /R:1 /W:1 /NP
    $robocopyExitCode = $LASTEXITCODE
    if ($robocopyExitCode -ge 8) {
      throw "Robocopy could not migrate Recordly userData (exit code $robocopyExitCode). The original profile was left in place."
    }

    $backupPath = "$systemUserData.kirobucket-backup"
    if (Test-Path -LiteralPath $backupPath) {
      $backupPath = "$backupPath-$(Get-Date -Format 'yyyyMMdd-HHmmss')"
    }
    Move-Item -LiteralPath $systemUserData -Destination $backupPath
    Write-Warning "Original Recordly profile retained as a migration backup: $backupPath"
  }
  else {
    Remove-Item -LiteralPath $systemUserData -Force
  }
}
else {
  New-Item -ItemType Directory -Path $persistUserData -Force | Out-Null
}

New-Item -ItemType Junction -Path $systemUserData -Target $persistUserData | Out-Null

$junction = Get-Item -LiteralPath $systemUserData -Force
if (-not $junction.Attributes.HasFlag([System.IO.FileAttributes]::ReparsePoint)) {
  throw 'Recordly userData Junction was not created.'
}
$junctionTarget = [string]$junction.Target
if ([string]::IsNullOrWhiteSpace($junctionTarget)) {
  throw 'Recordly userData Junction has no readable target.'
}
$junctionTarget = [System.IO.Path]::GetFullPath($junctionTarget).TrimEnd([char]92)
if (-not [string]::Equals($junctionTarget, $persistUserData, [System.StringComparison]::OrdinalIgnoreCase)) {
  throw "Recordly userData Junction points to '$junctionTarget' instead of '$persistUserData'."
}

Write-Host "Recordly userData now resolves through Scoop persist: $junctionTarget"
'@
Set-Content -LiteralPath (Join-Path $dir 'Prepare-RecordlyPersist.ps1') -Value $bootstrap -Encoding UTF8
